MOD = 1000000007

def factorial_mod(n, mod):
    result = 1
    for i in range(2, n + 1):
        result = (result * i) % mod
    return result

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    pairs = [(int(data[i]), int(data[i + 1])) for i in range(1, 2 * N, 2)]

    visited = [False] * (2 * N + 1)
    cycles = []

    for current, desired in pairs:
        if not visited[current]:
            cycle = []
            while not visited[current]:
                visited[current] = True
                cycle.append(current)
                current = desired
            if cycle and cycle[0] == current:
                cycles.append(cycle)

    result = 1
    for cycle in cycles:
        k = len(cycle)
        result = (result * factorial_mod(k, MOD)) % MOD

    print(result)

if __name__ == "__main__":
    main()
